-- res_overall  -> out/res_overall.csv
SELECT 
  count(*) AS complaints,
  count(*) FILTER (is_final) AS final_status, round(100.0*avg(is_final::INT),2) AS final_pct,
  count(*) FILTER (status='Resolved') AS resolved, count(*) FILTER (status='Closed') AS closed,
  count(*) FILTER (status='Rejected') AS rejected, count(*) FILTER (status='Open') AS open,
  count(*) FILTER (status='In Process') AS in_process, count(*) FILTER (status='Escalated') AS escalated,
  count(res_days_ts) AS n_with_open_and_close_ts,
  round(quantile_cont(res_days_ts,0.5),2) AS res_days_p50, round(quantile_cont(res_days_ts,0.75),2) AS res_days_p75,
  round(quantile_cont(res_days_ts,0.9),2) AS res_days_p90, round(avg(res_days_ts),2) AS res_days_mean,
  round(quantile_cont(resolution_days,0.5),1) AS col_resolution_days_p50,
  round(quantile_cont(resolution_days,0.75),1) AS col_resolution_days_p75,
  round(quantile_cont(resolution_days,0.9),1) AS col_resolution_days_p90,
  count(*) FILTER (sla_breached) AS sla_breached, round(100.0*avg(sla_breached::INT),2) AS sla_breach_pct_all,
  count(*) FILTER (sla_breached AND is_final) AS sla_breached_final,
  round(100.0*count(*) FILTER (sla_breached AND is_final)/NULLIF(count(*) FILTER (is_final),0),2) AS sla_breach_pct_final
 FROM cp;

