-- res_status_mix  -> out/res_status_mix.csv
SELECT cat_group, status, count(*) n,
  round(100.0*count(*)/sum(count(*)) OVER (PARTITION BY cat_group),2) pct,
  count(res_days_ts) n_with_dates, count(*) FILTER (sla_breached) sla_breached
  FROM cp GROUP BY 1,2 ORDER BY 1,3 DESC;

-- res_days_hist  -> out/res_days_hist.csv
SELECT cat_group, CAST(floor(res_days_ts) AS INT) AS day_floor, count(*) n
  FROM cp WHERE res_days_ts IS NOT NULL GROUP BY 1,2 ORDER BY 1,2;

-- res_check_ts_vs_column  -> out/res_check_ts_vs_column.csv
SELECT count(*) FILTER (res_days_ts IS NOT NULL) n_ts, count(resolution_days) n_col,
  count(*) FILTER (res_days_ts IS NOT NULL AND resolution_days IS NOT NULL AND abs(res_days_ts-resolution_days)>1) n_diff_gt1d
  FROM cp;

-- res_sla_vs_days  -> out/res_sla_vs_days.csv
SELECT sla_breached, count(*) n, count(res_days_ts) n_dates,
  round(quantile_cont(res_days_ts,0.5),2) p50, round(quantile_cont(res_days_ts,0.9),2) p90 FROM cp GROUP BY 1;

-- cost_columns_scan  -> out/cost_columns_scan.csv
SELECT table_name, column_name, data_type FROM information_schema.columns
  WHERE table_name NOT IN ('tx','cp') AND regexp_matches(lower(column_name),'cost|price|fee|salary|wage|amount|compens|duration|handl|effort|budget|value|time_seconds')
  ORDER BY 1,2;

-- cost_compensation_by_group  -> out/cost_compensation_by_group.csv
SELECT cat_group, COALESCE(currency,'(null)') currency, count(*) complaints,
  count(compensation_granted) n_comp, count(*) FILTER (compensation_granted>0) n_comp_gt0,
  round(sum(compensation_granted),2) sum_comp, round(median(compensation_granted),2) median_comp
  FROM cp GROUP BY 1,2 ORDER BY 1,2;

-- cost_callcenter_handle_time  -> out/cost_callcenter_handle_time.csv
SELECT reason_category, count(*) interactions, count(duration_seconds) n_duration,
  round(avg(duration_seconds),1) aht_sec_mean, round(median(duration_seconds),1) aht_sec_p50,
  round(avg(wait_time_seconds),1) wait_sec_mean, round(100*avg(was_resolved::INT),2) resolved_pct,
  round(100*avg(was_escalated::INT),2) escalated_pct, round(100*avg(requires_followup::INT),2) followup_pct
  FROM call_center_interactions GROUP BY 1 ORDER BY 2 DESC;

-- cost_callcenter_transaccional_by_country_segment  -> out/cost_callcenter_transaccional_by_country_segment.csv
SELECT c.country, c.segment, count(*) interactions,
  round(avg(i.duration_seconds),1) aht_sec_mean, round(100*avg(i.was_resolved::INT),2) resolved_pct
  FROM call_center_interactions i JOIN customers c USING (customer_id)
  WHERE i.reason_category='Transaccional' GROUP BY 1,2 ORDER BY 1,2;

-- cost_callcenter_by_channel_transaccional  -> out/cost_callcenter_by_channel_transaccional.csv
SELECT channel, count(*) interactions, round(avg(duration_seconds),1) aht_sec_mean,
  round(100*avg(was_resolved::INT),2) resolved_pct FROM call_center_interactions
  WHERE reason_category='Transaccional' GROUP BY 1 ORDER BY 2 DESC;
